partial<-subset(full,is.finite(FI30)&complete.cases(age,sex,race,cycle_adjust,NLR,MLR,SIRI,SII)&NLR>0&MLR>0&SIRI>0&SII>0);partial$variables$frail<-as.integer(partial$variables$FI30>.3);run(partial,m1,'FI30_M1',FALSE)
