for(m in markers)for(mod in c('age_group','sex','bmi','activity','smoking','alcohol')){d<-main;d$variables$x<-log(d$variables[[m]]);d$variables$moderator<-d$variables[[mod]];terms<-c(setdiff(m2,mod),'x*moderator');f<-fit(d,terms,paste0('Interaction_',mod),m);it<-if(is.null(f))character()else grep('x:moderator|moderator.*:x',names(coef(f)),value=TRUE);w<-if(length(it))wald(f,it,degf(d))else c(F=NA,p=NA);add('interactions',data.frame(marker=m,moderator=mod,F=w['F'],p=w['p'],df_num=length(it),df=degf(d),n=nrow(d$variables),status=if(is.finite(w['p']))'estimable'else'non-estimable'))
for(lev in levels(d$variables$moderator)){take<-d$variables$moderator==lev;n<-sum(take);ev<-sum(d$variables$frail[take]);bb<-ss<-NA_real_;if(!is.null(f)&&n>0&&ev>0&&ev<n){new<-d$variables[1,,drop=FALSE];new$moderator<-factor(lev,levels=levels(d$variables$moderator));new$x<-1;nn<-new;nn$x<-0;tt<-delete.response(terms(f));D<-model.matrix(tt,new,contrasts.arg=f$contrasts)-model.matrix(tt,nn,contrasts.arg=f$contrasts);D<-D[,names(coef(f)),drop=FALSE];bb<-drop(D%*%coef(f));ss<-sqrt(drop(D%*%vcov(f)%*%t(D)))};add('slopes',data.frame(marker=m,moderator=mod,level=lev,n=n,events=ev,non_events=n-ev,pooled_n=nrow(d$variables),OR=exp(bb),low=exp(bb-qt(.975,degf(d))*ss),high=exp(bb+qt(.975,degf(d))*ss),status=if(is.finite(bb))'estimable'else'non-estimable'))}}
for(n in c('continuous','quartile','trend','omnibus','spline','interactions')){z<-do.call(rbind,res[[n]]);z$p_holm<-z$p_BH<-NA_real_;fam<-if(n=='interactions')rep('interaction',nrow(z))else z$model;planned<-switch(n,quartile=12,interactions=24,4);for(g in unique(fam)){i<-fam==g;z$p_holm[i]<-p.adjust(z$p[i],'holm',n=planned);z$p_BH[i]<-p.adjust(z$p[i],'BH',n=planned)};if(n=='spline'){z$overall_p_holm<-ave(z$overall_p,z$model,FUN=function(x)p.adjust(x,'holm',n=4));z$overall_p_BH<-ave(z$overall_p,z$model,FUN=function(x)p.adjust(x,'BH',n=4))};writeout(z,switch(n,continuous='continuous_models',quartile='quartile_models',trend='trend_models',omnibus='omnibus_tests',spline='spline_tests',interactions='interactions'))}
writeout(do.call(rbind,res$slopes),'subgroup_slopes');writeout(do.call(rbind,res$curves),'curve_data');writeout(do.call(rbind,res$audit),'fit_audit');saveRDS(rows,file.path(out,'model_row_ids.rds'));saveRDS(bases,file.path(out,'basis_transformations.rds'));write_json(bases,file.path(out,'basis_transformations.json'),pretty=TRUE,digits=17,auto_unbox=TRUE);cat('MODEL PASS COMPLETE\n')
